#!/usr/bin/env python3
"""Ingest locations from the tools API → util/autogenerated/locations.py.

Locations are unusual: the list endpoint already includes the rich shape
(serviceList, activityList, buildingList, jobBoards, faction, subFactions,
keywords). Detail just adds path data we don't need yet.

Empty arrays are preserved as `[]` (the location has zero of that thing).
"""
from __future__ import annotations
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent.parent))
from util.scrapers.tools_api_client import ToolsAPIClient  # noqa: E402
from util.scrapers.tools_api_dump import dump_endpoint  # noqa: E402


def run(client: ToolsAPIClient, *, use_cache: bool = True) -> int:
    out = (
        Path(__file__).resolve().parent.parent
        / 'autogenerated' / 'locations.py'
    )
    n = dump_endpoint(
        client, 'locations', str(out), 'LOCATIONS',
        use_cache=use_cache,
        docstring=(
            'Locations — keyed by location id. Each entry preserves '
            'serviceList/activityList/buildingList/jobBoards/keywords/'
            'subFactions as empty arrays where applicable. faction is the '
            'primary faction (string).'
        ),
    )
    print(f'  [locations          ] {n:4d} entities → locations.py')
    return n


if __name__ == '__main__':
    raise SystemExit(0 if run(ToolsAPIClient()) else 1)
